const request = $json;
const body = request.body ?? request;

const nestedContact = body.contact ?? {};
const nestedHasIdentity = Boolean(
  nestedContact.id ||
  nestedContact.contact_id ||
  nestedContact.email ||
  nestedContact.phone
);

const contact = nestedHasIdentity ? nestedContact : body;
const opportunity = body.opportunity ?? {};

const custom =
  contact.customFields ??
  contact.custom_fields ??
  body.customFields ??
  body.custom_fields ??
  body.customData ??
  {};

const readField = (...keys) => {
  for (const key of keys) {
    if (body[key] !== undefined && body[key] !== "") return body[key];
    if (contact[key] !== undefined && contact[key] !== "") return contact[key];

    if (Array.isArray(custom)) {
      const match = custom.find(
        (field) =>
          field.id === key ||
          field.key === key ||
          field.name === key
      );

      const value = match?.value ?? match?.fieldValue;
      if (value !== undefined && value !== "") return value;
    } else if (custom[key] !== undefined && custom[key] !== "") {
      return custom[key];
    }
  }

  return null;
};

const derivedName = [
  contact.first_name ?? contact.firstName,
  contact.last_name ?? contact.lastName,
].filter(Boolean).join(" ");

return [{
  json: {
    source_system: "gohighlevel",
    received_at: new Date().toISOString(),

    contact_id:
      contact.contact_id ??
      contact.contactId ??
      contact.id ??
      body.contact_id ??
      body.contactId ??
      null,

    opportunity_id:
      opportunity.id ??
      body.opportunity_id ??
      body.opportunityId ??
      readField("opportunity_id") ??
      (body.opportunity_name ? body.id : null),

    first_name:
      contact.first_name ??
      contact.firstName ??
      body.first_name ??
      null,

    last_name:
      contact.last_name ??
      contact.lastName ??
      body.last_name ??
      null,

    full_name:
      contact.full_name ??
      contact.fullName ??
      body.full_name ??
      (derivedName || null),

    email: contact.email ?? body.email ?? null,
    phone: contact.phone ?? body.phone ?? null,

    lead_source: readField("Lead Source", "lead_source"),
    interested_in: readField("Interested In", "interested_in"),
    preferred_contact_method: readField(
      "Preferred Contact Method",
      "preferred_contact_method"
    ),
    lead_type: readField("Lead Type", "lead_type"),

    message:
      body.message?.body ??
      body.message ??
      contact.message ??
      null,

    pipeline_id:
      opportunity.pipelineId ??
      body.pipeline_id ??
      body.pipelineId ??
      null,

    pipeline_stage_id:
      opportunity.pipelineStageId ??
      body.pipeline_stage_id ??
      body.pipelineStageId ??
      null,

    pipeline_name:
      body.pipeline_name ??
      readField("pipeline_name"),

    pipeline_stage_name:
      body.pipeline_stage_name ??
      body.pipleline_stage ??
      readField("pipeline_stage_name"),

    raw_payload: body,
  },
}];

// Validation rule for this project: a lead needs a CRM contact ID and at least one contact method.
// A missing buying signal is NOT invalid; it is handled later as Needs Review.

const lead = $json;
const errors = [];
if (!lead.contact_id) errors.push('Missing GHL contact ID');
if (!lead.email && !lead.phone) errors.push('Missing both email and phone');

return [{
  json: {
    ...lead,
    validation: {
      valid: errors.length === 0,
      errors
    }
  }
}];

// This is the contract the later AI node must return.
// It prevents free-text AI answers from controlling CRM automation.

return [{
  json: {
    ...$json,
    ai_input: {
      lead: {
        name: $json.full_name,
        email: $json.email,
        phone: $json.phone,
        source: $json.lead_source,
        interested_in: $json.interested_in,
        lead_type: $json.lead_type,
        message: $json.message
      },
      required_output: {
        temperature: ['Hot', 'Warm', 'Cold'],
        qualification_status: ['Qualified', 'Partially Qualified', 'Not Qualified', 'Needs Review'],
        intent_score: 'integer from 0 to 100',
        timeline: ['Immediate', 'This Week', 'This Month', 'No Urgency', 'Unknown'],
        recommended_action: 'short action for sales team',
        reason: 'short evidence-based explanation'
      }
    }
  }
}];

