const originalLead = $('Build AI Qualification Prompt').first().json;

return $input.all().map((item) => {
  const qualification = item.json.output?.[0]?.content?.[0]?.text;

  if (!qualification || typeof qualification !== 'object') {
    throw new Error('AI qualification output is missing or invalid');
  }

  return {
    json: {
      ...originalLead,
      ...qualification,
      ai_model: 'gpt-5-mini',
      qualification_processed_at: new Date().toISOString(),
    },
  };
});

